import { writeFileSync } from 'node:fs';
// Read-only instrumentation: observe the real product-owned queue, never create or mutate it.
const timer = setInterval(() => {
  const queues = globalThis[Symbol.for('openclaw.systemEvents.queues')];
  if (!(queues instanceof Map) || !process.env.SLACK_PROOF_QUEUE_OUTPUT) return;
  const rows = [...queues.entries()].map(([sessionKey, entry]) => ({
    sessionKey, count: entry.queue.length,
    contextKeys: entry.queue.map(event => event.contextKey),
  }));
  writeFileSync(process.env.SLACK_PROOF_QUEUE_OUTPUT, JSON.stringify({ pid: process.pid, rows }));
}, 100);
timer.unref();
